    assign readback_array[29][1:0] = (decoded_reg_strb.EXT_TRNG_SRC_SEL && !decoded_req_is_wr) ? field_storage.EXT_TRNG_SRC_SEL.sel.value : '0;
    assign readback_array[29][63:2] = '0;
    assign readback_array[30][0:0] = (decoded_reg_strb.EXT_TRNG_SRC_SEL_LOCK && !decoded_req_is_wr) ? field_storage.EXT_TRNG_SRC_SEL_LOCK.lock.value : '0;
    assign readback_array[30][63:1] = '0;
    assign readback_array[31][31:0] = (decoded_reg_strb.SEP_VERSION_ID && !decoded_req_is_wr) ? 32'hdeadbeef : '0;
    assign readback_array[31][63:32] = '0;

    // Reduce the array
    always_comb begin
        automatic logic [63:0] readback_data_var;
        readback_done = decoded_req & ~decoded_req_is_wr;
        readback_err = '0;
        readback_data_var = '0;
        for(int i=0; i<32; i++) readback_data_var |= readback_array[i];
        readback_data = readback_data_var;
    end

    assign cpuif_rd_ack = readback_done;
    assign cpuif_rd_data = readback_data;
    assign cpuif_rd_err = readback_err;
endmodule
